def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(c for c in range(1, 10)
               if any(all(v == c for v in row) for row in grid)
               and any(all(grid[r][col] == c for r in range(h)) for col in range(w)))
    sep_rows = [r for r in range(h) if all(v == sep for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    row_starts = [0] + [r + 1 for r in sep_rows]
    col_starts = [0] + [c + 1 for c in sep_cols]
    panel_h, panel_w = sep_rows[0], sep_cols[0]

    # Find the larger object: this is the stencil repeated in each panel.
    motif = None
    for rs in row_starts:
        for cs in col_starts:
            counts = Counter(grid[rs+r][cs+c]
                             for r in range(panel_h) for c in range(panel_w)
                             if grid[rs+r][cs+c] not in (0, sep))
            candidates = [color for color, n in counts.items() if n > 4]
            if candidates:
                color = max(candidates, key=lambda c: counts[c])
                motif = [(r, c) for r in range(panel_h) for c in range(panel_w)
                         if grid[rs+r][cs+c] == color]
                break
        if motif is not None:
            break
    if motif is None:
        return [row[:] for row in grid]

    keys = []
    for rs in row_starts:
        keys.append(next((grid[rs+r][c] for r in range(panel_h) for c in range(panel_w)
                          if grid[rs+r][c] not in (0, sep)), 0))

    out = [row[:] for row in grid]
    # Erase the original key and stencil objects from every cell panel.
    for rs in row_starts:
        for cs in col_starts:
            for r in range(panel_h):
                for c in range(panel_w):
                    if out[rs+r][cs+c] != sep:
                        out[rs+r][cs+c] = 0
    # Stamp the stencil throughout each panel row, using that band's key color.
    for rs, key in zip(row_starts, keys):
        for cs in col_starts:
            for r, c in motif:
                out[rs+r][cs+c] = key
    return out

if __name__ == '__main__':
    pass
